 $('lightboxLoadFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1e6)throw Error('The lightbox file is too large.');loadData(await f.text());}catch(error){notify('Could not load: '+error.message);}};
 $('lightboxShowcase').onchange=e=>{const id=e.target.value;e.target.value='';if(!id)return;try{loadData(MieLightboxShowcases[id]);}catch(error){notify('Could not load showcase: '+error.message);}};
 $('lightboxUndoLoad').onclick=()=>{if(!previousLoad)return;const data=previousLoad;loadData(data,false);previousLoad=null;$('lightboxUndoLoad').hidden=true;notify('Previous lightbox restored.');};
