  for(const id of ['lightboxGain','lightboxDiameter','lightboxPitch','lightboxYaw','lightboxWalls']){const row=$(id).closest('label');if(paint)row.hidden=true;else if(['lightboxGain','lightboxPitch','lightboxYaw'].includes(id))row.hidden=false;}
