 function setPaint(values,all=false){const sample=collection.samples.find(s=>s.id===activeId);if(!sample)return;const clean=Model.clean({...sample,paint:{...sample.paint,...values}}).paint;for(const s of collection.samples)if(all||s.id===activeId)s.paint={...clean};paintUI();renderer?.setSamples(collection.samples,jobs);if(sampleDialog.open)fillContents(false);persist();}
