 function solidUI(){const enabled=['seidel','monolith'].includes(settings.container),sample=collection.samples.find(s=>s.id===activeId);$('lightboxSolidControls').hidden=!enabled;$('lightboxLycurgusNote').hidden=!(enabled&&loadedTitle.startsWith('Lycurgus'));for(const id of ['lightboxSolidLoading','lightboxSolidDiameter','lightboxSolidMatch'])$(id).disabled=!sample;if(!sample){$('lightboxSolidLoadingValue').textContent='Select a sample';$('lightboxSolidDiameterValue').textContent='';return;}const a=sample.solid||{loading:0,diameter:400};$('lightboxSolidLoading').value=100*a.loading;$('lightboxSolidLoadingValue').textContent=Model.fmt(100*a.loading)+' vol%';$('lightboxSolidDiameter').value=a.diameter;$('lightboxSolidDiameterValue').textContent='d = '+Model.fmt(a.diameter)+' nm';}
