 function seidelSceneUI(){solidUI();const solid=['seidel','monolith'].includes(settings.container);dialog.classList.toggle('lb-is-seidel',solid);$('lightboxSeidelScene').hidden=!solid;$('lightboxSeidelLogo').checked=!!settings.seidelLogo;$('lightboxSeidelFrontLight').checked=!!settings.seidelFrontLight;$('lightboxSeidelMatrix').value=settings.seidelMatrix;if(solid){$('lightboxWallControl').hidden=true;$('lightboxDiameterControl').hidden=true;$('lightboxContainerNote').hidden=true;$('lightboxScenePanel').querySelector('.lb-wetting-controls').hidden=true;$('lightboxScenePanel').querySelector('.lb-wetting-controls').nextElementSibling.hidden=true;$('lightboxSeidelSummary').textContent=settings.container==='monolith'?`16 × 45 × 1.48 mm. Gently curved solid, rounded edges. Nominal thickness matches the central barrel wall of Humpen.stl. Matrix: ${MieSolidMatrix.defs[settings.seidelMatrix].name}.`:`65 × 50 × 89 mm. Particle-filled ${MieSolidMatrix.defs[settings.seidelMatrix].name}, n = ${Model.fmt(MieSolidMatrix.nk(settings.seidelMatrix,550).n)} at λ = 550 nm. The interior is empty. Three samples maximum.`;}}
